<script>
import {markRaw} from 'vue'
import {
  Chart, ArcElement, BarElement, CategoryScale, LinearScale,
  Tooltip, Legend, DoughnutController, BarController,
} from 'chart.js'
import {BUDGET_URL} from '@/config/managers.config'

Chart.register(ArcElement, BarElement, CategoryScale, LinearScale,
    Tooltip, Legend, DoughnutController, BarController)

// ── Константы ───────────────────────────────────────────
const SPECIAL = new Set([
  'МЕРЕЖА (ФОТ деталізація)', 'Офіс Київ', 'Склад Київ',
  'Тендер', 'Сервер', 'Склад Смольная', 'Склад Київ ТМЦ',
  'Склад', 'Офіс', 'Кібер-Бульвар',
])

const MARGIN_EXCLUDED = new Set(['Сервіс Маяковського', 'Інтернет Магазин'])

const EXPENSE_FIELDS = [
  'rent', 'security', 'transport', 'fuel', 'insurance', 'other_services',
  'utilities', 'logistics', 'communication', 'bank_fees', 'writeoffs',
  'repr_expenses', 'repairs', 'tools', 'salary', 'salary_other', 'salary_travel',
  'marketing', 'taxes',
]

const MAINTAIN_FIELDS = [
  'rent', 'security', 'transport', 'fuel', 'insurance', 'other_services',
  'utilities', 'logistics', 'communication', 'bank_fees', 'writeoffs', 'repr_expenses',
]

const PIE_COLORS = [
  '#6366f1', '#22c55e', '#f59e0b', '#ef4444', '#14b8a6',
  '#8b5cf6', '#f97316', '#06b6d4', '#84cc16', '#ec4899',
  '#a78bfa', '#fb923c', '#34d399', '#fbbf24',
]

// ── Картки магазинів: фіксований масштаб рендеру ─────────────
// На відміну від інших callout-pie (Офіс/Склад/верхні три), де
// SVG масштабується "під контейнер", тут масштаб ФІКСОВАНИЙ — це
// єдиний спосіб гарантувати однаковий розмір кола й тексту на
// картках з різною кількістю категорій. 0.30 — середнє між
// поточним масштабом Офіс Київ (~0.42) і типовою карткою магазину
// з багатьма категоріями (~0.18). STORE_CARD_MAX_W — аварійна межа
// ширини (530px): якщо колись трапиться магазин з аномально
// широким розкидом лейблів, масштаб додатково притиснеться, щоб
// не вилізти за межу — однаково для всіх карток одразу (бо ширина
// в calloutGlobalDims спільна), тож однаковість розміру кола не
// ламається навіть у цьому крайньому випадку.
const STORE_PIE_SCALE = 0.30
const STORE_CARD_MAX_W = 530
// Нижня межа масштабу кола при звуженні екрана. Текст лишається
// фіксованого розміру (через зворотний масштаб у шаблоні), тож чим
// сильніше стискається коло, тим "більшим" текст виявляється відносно
// вже порахованих відступів між лейблами (CALLOUT_ROW_GAP/GAP_X) —
// на реальних магазинах перевірено, що відступи витримують збільшення
// тексту приблизно до ×1.26–1.36 без накладання. 0.25 дає запас
// (×1.2 максимум), тобто коло не стискається більш ніж на ~17%.
//const STORE_PIE_SCALE_FLOOR = 0.25

// ── Картки магазинів: структура витрат (callout-пиріг) ──────
// Лейбли йдуть через this.$t('budget.fields.*') (бо залежать від локалі),
// а кольори прив'язані до ключа поля, а не до тексту лейбла — інакше
// при перекладі лейбла на іншу мову lookup кольору зламається.
const STORE_CAT_COLORS = {
  salary: '#1150a1',
  rent: '#39a2ed',
  taxes: '#d97706',
  marketing: '#dc2626',
  utilities: '#13cd39',
  logistics: '#7c3aed',
  bank_fees: '#ea580c',
  communication: '#a6a036',
  security: '#65a30d',
  tools: '#db2777',
  writeoffs: '#7c6fd6',
  repairs: '#ea7c1f',
  fuel: '#0d9b8a',
  insurance: '#ca8a04',
  transport: '#e11d48',
  repr_expenses: '#059669',
  salary_other: '#0284c7',
  salary_travel: '#c026d3',
  other_services: '#475569',
}

const CALLOUT_R = 360
const CALLOUT_SIDE_GAP = 25
const CALLOUT_LABEL_GAP = 30
const CALLOUT_LINE_H = 32
const CALLOUT_CHAR_W = 15.4
const CALLOUT_WRAP_CHARS = 13

const CALLOUT_ROW_GAP = 40
const CALLOUT_GAP_X = 50

const CALLOUT_CROSS_BUFFER = 24
const calloutElbow = r => r + CALLOUT_SIDE_GAP
const calloutLabel = r => r + CALLOUT_SIDE_GAP + CALLOUT_LABEL_GAP

function calloutWrapLabel(label) {
  if (label.length <= CALLOUT_WRAP_CHARS) return [label]
  const mid = Math.floor(label.length / 2)
  let idx = label.lastIndexOf(' ', mid)
  if (idx <= 0) idx = label.indexOf(' ', mid)
  if (idx <= 0) return [label]
  return [label.slice(0, idx), label.slice(idx + 1)]
}

function calloutRowH(it) {
  return (it.lines.length + 2) * CALLOUT_LINE_H
}

function calloutBuildPie(items, r = CALLOUT_R) {
  const PI = Math.PI, cos = Math.cos, sin = Math.sin
  const total = items.reduce((s, d) => s + d.value, 0)
  let angle = -PI / 2
  return items.map(item => {
    const sweep = total > 0 ? (item.value / total) * 2 * PI : 0
    const sA = angle, eA = angle + sweep, midA = angle + sweep / 2
    angle = eA
    const large = sweep > PI ? 1 : 0
    const p1 = [r * cos(sA), r * sin(sA)]
    const p2 = [r * cos(eA), r * sin(eA)]
    const path = `M0,0 L${p1[0].toFixed(2)},${p1[1].toFixed(2)} A${r},${r},0,${large},1,${p2[0].toFixed(2)},${p2[1].toFixed(2)} Z`
    return {...item, path, midA, total}
  })
}

function calloutClassify(segs, r = CALLOUT_R) {
  return segs.map(s => {
    const c = Math.cos(s.midA), sn = Math.sin(s.midA)
    const zone = Math.abs(c) >= Math.abs(sn) ? (c > 0 ? 'right' : 'left') : (sn > 0 ? 'bottom' : 'top')
    const lines = calloutWrapLabel(s.label)
    const valueStr = Math.round(s.value).toLocaleString('uk-UA').replace(/,/g, ' ')
    const pctStr = s.total > 0 ? (s.value / s.total * 100).toFixed(1) + '%' : '0%'
    const textWidth = Math.max(...lines.map(l => l.length * CALLOUT_CHAR_W), valueStr.length * CALLOUT_CHAR_W, pctStr.length * CALLOUT_CHAR_W)
    const edgeX = r * c, edgeY = r * sn
    return {...s, zone, lines, valueStr, pctStr, textWidth, edgeX, edgeY}
  })
}

function calloutResolveVertical(group) {
  group.forEach(it => {
    it.rawY = it.edgeY
  })
  group.sort((a, b) => a.rawY - b.rawY)
  for (let i = 1; i < group.length; i++) {
    const minGap = (calloutRowH(group[i - 1]) + calloutRowH(group[i])) / 2 + CALLOUT_ROW_GAP
    if (group[i].rawY - group[i - 1].rawY < minGap) group[i].rawY = group[i - 1].rawY + minGap
  }
  for (let i = group.length - 2; i >= 0; i--) {
    const minGap = (calloutRowH(group[i]) + calloutRowH(group[i + 1])) / 2 + CALLOUT_ROW_GAP
    if (group[i + 1].rawY - group[i].rawY < minGap) group[i].rawY = group[i + 1].rawY - minGap
  }
  if (group.length) {
    const center = (group[0].rawY + group[group.length - 1].rawY) / 2
    group.forEach(it => {
      it.rawY -= center
    })
  }
}

function calloutResolveHorizontal(group) {
  group.forEach(it => {
    it.rawX = it.edgeX
  })
  group.sort((a, b) => a.rawX - b.rawX)
  for (let i = 1; i < group.length; i++) {
    const minGap = (group[i - 1].textWidth + group[i].textWidth) / 2 + CALLOUT_GAP_X
    if (group[i].rawX - group[i - 1].rawX < minGap) group[i].rawX = group[i - 1].rawX + minGap
  }
  for (let i = group.length - 2; i >= 0; i--) {
    const minGap = (group[i].textWidth + group[i + 1].textWidth) / 2 + CALLOUT_GAP_X
    if (group[i + 1].rawX - group[i].rawX < minGap) group[i].rawX = group[i + 1].rawX - minGap
  }
  if (group.length) {
    const center = (group[0].rawX + group[group.length - 1].rawX) / 2
    group.forEach(it => {
      it.rawX -= center
    })
  }
}

function calloutLineBaselinesV(rawY, totalLines) {
  const blockTop = rawY - (totalLines * CALLOUT_LINE_H) / 2 + CALLOUT_LINE_H * 0.8
  return Array.from({length: totalLines}, (_, i) => blockTop + i * CALLOUT_LINE_H)
}

function calloutLineBaselinesH(labelY, totalLines, isTop) {
  return Array.from({length: totalLines}, (_, i) =>
      isTop ? labelY - (totalLines - 1 - i) * CALLOUT_LINE_H : labelY + i * CALLOUT_LINE_H)
}

function calloutFinalize(item, r = CALLOUT_R, extraPush = 0) {
  const lines = [...item.lines, item.valueStr, item.pctStr]
  let textX, textAnchor, baselines, polyline
  if (item.zone === 'left' || item.zone === 'right') {
    const sign = item.zone === 'left' ? -1 : 1
    textX = sign * calloutLabel(r)
    textAnchor = item.zone === 'left' ? 'end' : 'start'
    baselines = calloutLineBaselinesV(item.rawY, lines.length)
    const elbowX = sign * calloutElbow(r)
    polyline = `${item.edgeX.toFixed(1)},${item.edgeY.toFixed(1)} ${elbowX.toFixed(1)},${item.rawY.toFixed(1)} ${textX},${item.rawY.toFixed(1)}`
  } else {
    const sign = item.zone === 'top' ? -1 : 1
    const elbow = calloutElbow(r) + extraPush
    const labelDist = calloutLabel(r) + extraPush
    const labelY = sign * labelDist
    textX = item.rawX
    textAnchor = 'middle'
    baselines = calloutLineBaselinesH(labelY, lines.length, item.zone === 'top')
    const elbowY = sign * elbow
    polyline = `${item.edgeX.toFixed(1)},${item.edgeY.toFixed(1)} ${item.rawX.toFixed(1)},${elbowY.toFixed(1)} ${item.rawX.toFixed(1)},${labelY}`
  }
  const renderLines = lines.map((text, li) => {
    let color
    if (li === lines.length - 1) color = '#94a3b8'      // %
    else if (li === lines.length - 2) color = '#1e293b' // значення
    else color = item.color                              // назва
    return {text, y: baselines[li].toFixed(1), color}
  })
  return {...item, textX, textAnchor, polyline, renderLines}
}

export default {
  name: 'BudgetPage',

  directives: {
    clickOutside: {
      mounted(el, binding) {
        el._clickOutside = (e) => {
          if (!el.contains(e.target)) binding.value(e)
        }
        document.addEventListener('click', el._clickOutside)
      },
      unmounted(el) {
        document.removeEventListener('click', el._clickOutside)
      },
    },
  },

  data() {
    return {
      loading: true,
      error: null,
      rawData: [],
      charts: markRaw({}),
      screenWidth: typeof window !== 'undefined' ? window.innerWidth : 1024,
      profitSortBy: 'op',
      salSortBy: 'profit', // 'pct' | 'profit'
      selectedPeriod: '',
      periodMenuOpen: false,
      selectedStoreForPopup: null, // магазин для pop-up (об'єкт store)
      showStorePopup: false, // показувати pop-up чи ні
    }
  },

  computed: {
    isMobile() {
      return this.screenWidth < 640
    },

    availablePeriods() {
      const seen = new Set()
      return this.rawData
          .map(r => r.time)
          .filter(t => t && !seen.has(t) && seen.add(t))
    },

    // Єдине джерело даних для всіх computed — фільтрується за обраним періодом
    filteredData() {
      if (!this.selectedPeriod) return this.rawData
      return this.rawData.filter(r => r.time === this.selectedPeriod)
    },

    period() {
      return this.selectedPeriod || this.rawData[0]?.time || ''
    },

    storeRows() {
      return this.filteredData.filter(r => !SPECIAL.has(r.store))
    },

    fotRow() {
      return this.filteredData.find(r => r.store === 'МЕРЕЖА (ФОТ деталізація)') || {}
    },

    ofisKyiv() {
      return this.filteredData.find(r => r.store === 'Офіс Київ') || null
    },

    skladKyiv() {
      return this.filteredData.find(r => r.store === 'Склад Київ') || null
    },

    officeCalloutLayouts() {
      const list = []
      if (this.ofisKyiv) list.push({
        key: 'ofis', title: this.$t('budget.sectionOfficePie'), icon: '🏢',
        headerClass: 'office-header--purple', store: this.ofisKyiv,
        layout: this.buildStoreLayout(this.ofisKyiv, 10),
      })
      if (this.skladKyiv) list.push({
        key: 'sklad', title: this.$t('budget.sectionWarehousePie'), icon: '🏭',
        headerClass: 'office-header--teal', store: this.skladKyiv,
        layout: this.buildStoreLayout(this.skladKyiv, 10),
      })
      return list
    },

    officeCalloutDims() {
      // Ширина спільна (для однакового масштабу кола), висота — своя
      // для Офісу й Складу окремо (entry.layout.halfHeight), без зайвого пустого місця.
      if (!this.officeCalloutLayouts.length) return {halfWidth: CALLOUT_R}
      return {halfWidth: Math.max(CALLOUT_R, ...this.officeCalloutLayouts.map(e => e.layout.halfWidth))}
    },

    // ── KPI ───────────────────────────────────────────────
    kpiBase() {
      const rows = this.allExpRows
      const rev = rows.reduce((s, r) => s + this.n(r.revenue), 0)
      const prof = rows.reduce((s, r) => s + this.n(r.profit), 0)
      const exp = rows.reduce((s, r) => s + this.rowExpenses(r), 0)
      return {rev, prof, exp, net: prof - exp}
    },

    kpiCards() {
      const {rev, prof, exp, net} = this.kpiBase
      return [
        {
          key: 'rev', label: this.$t('budget.kpiRevenue'),
          value: this.fmt(rev), icon: 'mdi-cash-multiple',
          cls: 'kpi-blue', pct: 100, ringColor: 'rgba(255,255,255,0.6)',
          sub: `100% від доходу`,
        },
        {
          key: 'prof', label: this.$t('budget.kpiProfit'),
          value: this.fmt(prof), icon: 'mdi-trending-up',
          cls: 'kpi-green',
          pct: Math.min(rev > 0 ? (prof / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? prof / rev * 100 : 0).toFixed(1)}% від доходу`,
        },
        {
          key: 'exp', label: this.$t('budget.kpiExpenses'),
          value: this.fmt(exp), icon: 'mdi-cash-minus',
          cls: 'kpi-orange',
          pct: Math.min(rev > 0 ? (exp / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? exp / rev * 100 : 0).toFixed(1)}% від доходу`,
        },
        {
          key: 'net', label: this.$t('budget.kpiNet'),
          value: this.fmt(net), icon: net >= 0 ? 'mdi-star-circle' : 'mdi-alert',
          cls: net >= 0 ? 'kpi-purple' : 'kpi-red',
          pct: Math.min(rev > 0 ? Math.abs(net / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? net / rev * 100 : 0).toFixed(2)}% від доходу`,
        },
      ]
    },

    // ── Treemap data ──────────────────────────────────────
    revenueTreemap() {
      return this.filteredData
          .filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)' && this.n(r.revenue) > 0)
          .map(r => ({store: r.store, value: this.n(r.revenue)}))
          .sort((a, b) => b.value - a.value)
    },

    expenseTreemap() {
      return this.filteredData
          .filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)' && this.rowExpenses(r) > 0)
          .map(r => ({store: r.store, value: this.rowExpenses(r)}))
          .sort((a, b) => b.value - a.value)
    },

    revenueTreemapCells() {
      const COLORS = [
        '#4f46e5', '#2563eb', '#0891b2', '#059669', '#7c3aed',
        '#b45309', '#be185d', '#0d9488', '#1d4ed8', '#6d28d9',
        '#047857', '#b91c1c', '#0369a1', '#4338ca', '#0e7490',
        '#065f46', '#7e22ce', '#92400e', '#1e40af', '#166534',
        '#831843', '#1e3a8a', '#134e4a', '#3730a3', '#78350f',
      ]
      return this.computeTreemapLayout(this.revenueTreemap, COLORS, this.isMobile)
    },

    expenseTreemapCells() {
      const COLORS = [
        '#dc2626', '#ea580c', '#d97706', '#b45309', '#92400e',
        '#9f1239', '#7f1d1d', '#c2410c', '#a16207', '#78350f',
        '#6366f1', '#7c3aed', '#0891b2', '#059669', '#1d4ed8',
        '#be185d', '#0d9488', '#4338ca', '#0e7490', '#166534',
        '#64748b', '#334155', '#1e293b', '#4b5563', '#374151',
      ]
      return this.computeTreemapLayout(this.expenseTreemap, COLORS, this.isMobile)
    },

    // Все строки для финансовых расчётов (включая Офіс, Склад, ІМ)
    allExpRows() {
      return this.filteredData.filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)')
    },

    // ── Pie charts data ───────────────────────────────────
    expCatData() {
      const rows = this.allExpRows
      const sum = (fields) => rows.reduce((s, r) => s + fields.reduce((ss, f) => ss + this.n(r[f]), 0), 0)
      return [
        {label: this.$t('budget.catMaintain'), value: sum(MAINTAIN_FIELDS), color: PIE_COLORS[0]},
        {label: this.$t('budget.catRepairs'), value: sum(['repairs', 'tools']), color: PIE_COLORS[1]},
        {
          label: this.$t('budget.catPersonnel'),
          value: sum(['salary', 'salary_other', 'salary_travel']),
          color: PIE_COLORS[2]
        },
        {label: this.$t('budget.catMarketing'), value: sum(['marketing']), color: PIE_COLORS[3]},
        {label: this.$t('budget.catTaxes'), value: sum(['taxes']), color: PIE_COLORS[4]},
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    maintainData() {
      const rows = this.allExpRows
      return MAINTAIN_FIELDS.map((f, i) => ({
        label: this.$t('budget.fields.' + f),
        value: rows.reduce((s, r) => s + this.n(r[f]), 0),
        color: PIE_COLORS[i % PIE_COLORS.length],
      })).filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    fotData() {
      // Усі компоненти ФОТ — з рядка «МЕРЕЖА (ФОТ деталізація)»,
      // який містить сітковий бреакдаун по типах оплати.
      // salary_other і salary_travel відсутні в МЕРЕЖА →
      // беремо їх сумою по всіх рядках (вони не входять до основних 5 компонентів).
      const fot = this.fotRow
      const rows = this.allExpRows
      const salOther = rows.reduce((s, r) => s + this.n(r.salary_other), 0)
      const salTravel = rows.reduce((s, r) => s + this.n(r.salary_travel), 0)
      return [
        {label: this.$t('budget.fot.rate'), value: this.n(fot.salary_rate), color: PIE_COLORS[0]},
        {label: this.$t('budget.fot.pctSales'), value: this.n(fot.salary_pct_sales), color: PIE_COLORS[1]},
        {label: this.$t('budget.fot.bonuses'), value: this.n(fot.salary_bonuses), color: PIE_COLORS[2]},
        {label: this.$t('budget.fot.freelance'), value: this.n(fot.salary_freelance), color: PIE_COLORS[3]},
        {label: this.$t('budget.fot.vacation'), value: this.n(fot.salary_vacation), color: PIE_COLORS[4]},
        {label: this.$t('budget.fields.salary_other'), value: salOther, color: PIE_COLORS[5]},
        {label: this.$t('budget.fields.salary_travel'), value: salTravel, color: PIE_COLORS[6]},
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    // ── Variant B computed ────────────────────────────────
    expCatCalloutLayout() {
      return this.buildCalloutLayout(this.expCatData)
    },
    maintainCalloutLayout() {
      return this.buildCalloutLayout(this.maintainData)
    },
    fotCalloutLayout() {
      return this.buildCalloutLayout(this.fotData)
    },
    topPiesLayouts() {
      return [
        {
          key: 'expCat', title: this.$t('budget.sectionExpCat'), icon: '📊',
          headerClass: 'office-header--amber', layout: this.expCatCalloutLayout,
        },
        {
          key: 'fot', title: this.$t('budget.sectionFot'), icon: '👥',
          headerClass: 'office-header--green', layout: this.fotCalloutLayout,
        },
        {
          key: 'maintain', title: this.$t('budget.sectionMaintain'), icon: '🔧',
          headerClass: 'office-header--blue', layout: this.maintainCalloutLayout,
        },
      ]
    },
    topPiesCalloutDims() {
      // Ширина спільна для всіх трьох (як у Офіс/Склад) — однаковий масштаб
      // кола й тексту. Висота — своя для кожного (без зайвого пустого місця).
      return {halfWidth: Math.max(CALLOUT_R, ...this.topPiesLayouts.map(e => e.layout.halfWidth))}
    },

    // Pop-up магазину — побудована як копія top-pies структури
    popupStoreLayout() {
      if (!this.selectedStoreForPopup) return {items: [], halfWidth: CALLOUT_R, halfHeight: CALLOUT_R, total: 0}
      return this.buildStoreLayout(this.selectedStoreForPopup, null, true, CALLOUT_R)
    },

    popupStoreCalloutDims() {
      // Ширина для pop-up магазину (як у top-pies)
      if (!this.selectedStoreForPopup) return {halfWidth: CALLOUT_R}
      const layout = this.popupStoreLayout
      return {halfWidth: Math.max(CALLOUT_R, layout.halfWidth)}
    },

    // Об'єднані дані для горизонтального графіку прибутку
    combinedProfitRows() {
      const rows = this.storeRows.map(r => ({
        ...r,
        _op: this.rowOpProfit(r),
        _net: this.n(r.net_profit),
      }))
      return this.profitSortBy === 'net'
          ? rows.sort((a, b) => b._net - a._net)
          : rows.sort((a, b) => b._op - a._op)
    },
    // ── Rankings (sorted) ─────────────────────────────────
    storesSortedByMargin() {
      // Маржинальність = валовий прибуток / дохід
      return [...this.storeRows]
          .filter(r => !MARGIN_EXCLUDED.has(r.store))
          .map(r => ({...r, _margin: this.n(r.revenue) > 0 ? this.n(r.profit) / this.n(r.revenue) : 0}))
          .sort((a, b) => b._margin - a._margin)
    },

    storesSortedByRentab() {
      // Рентабельність = (валовий прибуток - витрати) / дохід
      return [...this.storeRows]
          .filter(r => !MARGIN_EXCLUDED.has(r.store))
          .map(r => ({
            ...r,
            _rentab: this.rowProfitability(r),
            _rentabAfter: this.rowProfitabilityAfter(r),
          }))
          .sort((a, b) => b._rentab - a._rentab)
    },

    storesSortedByOpProfit() {
      // Прибуток від діяльності = валовий прибуток - операційні витрати
      return [...this.storeRows]
          .map(r => ({...r, _op: this.rowOpProfit(r)}))
          .sort((a, b) => b._op - a._op)
    },

    // Радіус кола для карток магазинів — звужується на вузьких екранах,
    // щоб картка фізично влазила в менший простір. Розмір тексту й
    // масштаб рендеру (STORE_PIE_SCALE) при цьому НЕ змінюються — вони
    // фіксовані завжди, тож шрифт лишається того самого розміру, що й
    // на широкому екрані. Адаптивність починається з 600px (нижче —
    // телефони, де потрібне сжаття кола, але текст залишається незмінним).
    storeCalloutR() {
      if (this.screenWidth < 600) return 240
      if (this.screenWidth < 1000) return 280
      if (this.screenWidth < 1600) return 320
      return CALLOUT_R
    },

    storeCalloutLayouts() {
      // Картки магазинів: callout-пиріг структури витрат для кожного магазину.
      return this.storesSortedByOpProfit.map((store, idx) => ({
        store, idx, layout: this.buildStoreLayout(store, null, true, this.storeCalloutR),
      }))
    },

    calloutGlobalDims() {
      // Ширина спільна для всіх карток (щоб коло й текст мали однаковий
      // масштаб), а висота — своя для кожної картки (рахується окремо
      // в entry.layout.halfHeight), щоб не лишалось зайвого пустого місця.
      const layouts = this.storeCalloutLayouts.map(s => s.layout)
      if (!layouts.length) return {halfWidth: CALLOUT_R}
      return {halfWidth: Math.max(CALLOUT_R, ...layouts.map(l => l.halfWidth))}
    },

    // Фіксований масштаб рендеру карток магазинів. Зазвичай = STORE_PIE_SCALE
    // (однаковий розмір кола й тексту на всіх картках); якщо спільна ширина
    // (calloutGlobalDims) при цьому масштабі вилазить за STORE_CARD_MAX_W —
    // притискається рівно настільки, щоб вкластись. Притискання діє одразу
    // на всі картки (бо ширина спільна), тож однаковість не порушується.
    storeCalloutRenderScale() {
      const naturalW = this.calloutGlobalDims.halfWidth * 2
      return Math.min(STORE_PIE_SCALE, STORE_CARD_MAX_W / naturalW)
    },

    // Піксельна ширина SVG — однакова для всіх карток магазинів.
    storeCalloutPxWidth() {
      return this.calloutGlobalDims.halfWidth * 2 * this.storeCalloutRenderScale
    },

    storesSortedBySalPct() {
      // Обидва показники відповідають рядкам 82-83 оригінального Excel:
      //   _salRev    = salary_pct_profit  — готове значення з JSON (комісійна ЗП / валовий прибуток)
      //   _salProfit = salary / profit    — загальна ЗП / валовий прибуток
      // Виключаємо рядки де salary_pct_profit відсутній (IM, Сервіс) — для них метрика не рахується
      return [...this.storeRows]
          .filter(r => this.n(r.profit) > 0 && r.salary_pct_profit !== '' && r.salary_pct_profit != null)
          .map(r => {
            const profit = this.n(r.profit)
            const op = this.rowOpProfit(r)
            return {
              ...r,
              _op: op,
              _salRev: this.n(r.salary_pct_profit),          // з JSON напряму
              _salProfit: this.n(r.salary) / profit,            // загальна / прибуток
            }
          })
          .sort((a, b) => this.salSortBy === 'pct'
              ? b._salRev - a._salRev
              : b._salProfit - a._salProfit)
    },

    isNarrowChart() {
      return this.screenWidth <= 1000
    },
    chartCardHeight() {
      if (this.isNarrowChart) {
        return Math.max(500, this.storesSortedByMargin.length * 26) + 'px'
      }
      return '480px'
    },
    salChartHeight() {
      if (this.isNarrowChart) {
        return Math.max(500, this.storesSortedBySalPct.length * 26) + 'px'
      }
      return '480px'
    },
    profitChartHeight() {
      if (this.isNarrowChart) {
        return Math.max(500, this.combinedProfitRows.length * 26) + 'px'
      }
      return '480px'
    },
  },

  watch: {
    selectedPeriod() {
      // Чекаємо поки Vue перемалює DOM з новими даними, тоді перебудовуємо графіки
      this.$nextTick(() => this.initCharts())
    },
    screenWidth() {
      // При перетині брейкпойнту 1000px — перебудовуємо тільки основні графіки
      this.$nextTick(() => this.initCharts())
    },
    salSortBy() {
      this.$nextTick(() => this._buildSalChart())
    },
    profitSortBy() {
      this.$nextTick(() => this._buildProfitChart())
    },
    '$i18n.locale'() {
      // Лейбли датасетів Chart.js малюються імперативно на canvas і не
      // реагують на Vue-реактивність самі — пересобираємо графіки руками.
      this.$nextTick(() => this.initCharts())
    },
  },

  async mounted() {
    window.addEventListener('resize', this._onResize)
    window.addEventListener('keydown', this._onKeydown)
    await this.loadData()
  },

  beforeUnmount() {
    window.removeEventListener('resize', this._onResize)
    window.removeEventListener('keydown', this._onKeydown)
    clearTimeout(this._resizeTimer)
    // Якщо компонент розмонтовується (наприклад, перехід на іншу сторінку)
    // поки pop-up відкритий — обов'язково повертаємо скрол сторінці,
    // інакше body.overflow='hidden' лишиться назавжди й зламає скрол всюди.
    document.body.style.overflow = 'auto'
    Object.values(this.charts).forEach(c => c.destroy())
  },

  methods: {
    openStorePopup(store) {
      this.selectedStoreForPopup = store
      this.showStorePopup = true
      // Запобігаємо скролю сторінки коли відкритий pop-up
      document.body.style.overflow = 'hidden'
    },

    closeStorePopup() {
      this.showStorePopup = false
      this.selectedStoreForPopup = null
      document.body.style.overflow = 'auto'
    },

    _buildSalChart() {
      const rows = this.storesSortedBySalPct
      const axis = this.isNarrowChart ? 'y' : 'x'
      this.makeVBar('chartSalPct', rows.map(r => r.store), [
        {
          data: rows.map(r => r._salRev),
          backgroundColor: 'rgba(249,115,22,0.85)',
          borderRadius: 3,
          label: this.$t('budget.salaryToRev'),
        },
        {
          data: rows.map(r => r._salProfit),
          backgroundColor: 'rgba(34,197,94,0.85)',
          borderRadius: 3,
          label: this.$t('budget.salaryToProfit'),
        },
      ], {
        pct: true,
        indexAxis: axis,
        legendColors: ['rgba(249,115,22,0.85)', 'rgba(34,197,94,0.85)'],
      })
    },

    _buildProfitChart() {
      const rows = this.combinedProfitRows
      const axis = this.isNarrowChart ? 'y' : 'x'
      this.makeVBar('chartProfit', rows.map(r => r.store), [
        {
          data: rows.map(r => r._op),
          backgroundColor: rows.map(r => r._op >= 0 ? 'rgba(99,102,241,0.85)' : 'rgba(239,68,68,0.85)'),
          borderRadius: 3,
          label: this.$t('budget.opProfit'),
        },
        {
          data: rows.map(r => r._net),
          backgroundColor: rows.map(r => r._net >= 0 ? 'rgba(34,197,94,0.85)' : 'rgba(239,68,68,0.7)'),
          borderRadius: 3,
          label: this.$t('budget.kpiNet'),
        },
      ], {
        indexAxis: axis,
        legendColors: ['rgba(99,102,241,0.85)', 'rgba(34,197,94,0.85)'],
      })
    },

    // ── Утилиты ───────────────────────────────────────────
    n: v => Number(v) || 0,
    fmt: v => Math.round(v).toLocaleString('uk-UA'),
    fmtM: v => {
      const abs = Math.abs(v)
      if (abs >= 1_000_000) return (v / 1_000_000).toFixed(2) + ' млн'
      if (abs >= 1_000) return (v / 1_000).toFixed(1) + ' тис'
      return Math.round(v).toString()
    },
    fmtK: v => Math.abs(v) >= 1000 ? (v / 1000).toFixed(1) + 'т' : Math.round(v).toString(),
    fmtPct: v => (v * 100).toFixed(1) + '%',

    rowExpenses(r) {
      return EXPENSE_FIELDS.reduce((s, f) => s + this.n(r[f]), 0)
    },
    rowOpProfit(r) {
      return this.n(r.profit) - this.rowExpenses(r)
    },
    rowMargin(r) {
      const rev = this.n(r.revenue);
      return rev > 0 ? this.n(r.profit) / rev : 0
    },
    rowProfitability(r) {
      const rev = this.n(r.revenue)
      return rev > 0 ? this.rowOpProfit(r) / rev : 0
    },
    rowProfitabilityAfter(r) {
      // rentab_after приходить готовим з JSON (РЕНТАБЕЛЬНІСТЬ ПІСЛЯ ВІДРАХУВАНЬ НА ОФІС%).
      // Для ІМ та Сервіс Маяковського поле порожнє — повертаємо 0.
      const v = r.rentab_after
      if (v !== '' && v !== null && v !== undefined) return this.n(v)
      return 0
    },

    _onResize() {
      // Дебаунс: під час перетягування краю вікна resize стріляє десятки
      // разів на секунду — без затримки це викликало б повне пересборювання
      // 4 Chart.js графіків (initCharts) на кожен тик, що відчутно гальмує.
      clearTimeout(this._resizeTimer)
      this._resizeTimer = setTimeout(() => {
        this.screenWidth = window.innerWidth
      }, 150)
    },

    _onKeydown(e) {
      if (e.key === 'Escape' && this.showStorePopup) this.closeStorePopup()
    },

    // ── Squarified Treemap ────────────────────────────────
    // Координатна система залежить від орієнтації:
    //   Desktop: 1000×500 (альбомна) — контейнер 460px
    //   Mobile:  500×800 (портретна) — контейнер 680px
    computeTreemapLayout(items, colors, mobile = false) {
      if (!items.length) return []
      const W = mobile ? 500 : 1000
      const H = mobile ? 800 : 500
      const total = items.reduce((s, i) => s + i.value, 0)
      const normed = items.map((i, idx) => ({
        ...i,
        _area: (i.value / total) * W * H,
        color: colors[idx % colors.length],
      }))
      const result = []
      this._tmSquarify(normed, 0, 0, W, H, result)
      return result.map(r => ({
        store: r.store,
        value: r.value,
        color: r.color,
        xPct: r._x / W * 100,
        yPct: r._y / H * 100,
        wPct: r._w / W * 100,
        hPct: r._h / H * 100,
      }))
    },

    _tmWorst(row, side) {
      if (!row.length || !side) return Infinity
      const s = row.reduce((a, i) => a + i._area, 0)
      const mx = Math.max(...row.map(i => i._area))
      const mn = Math.min(...row.map(i => i._area))
      return Math.max(side * side * mx / (s * s), s * s / (side * side * mn))
    },

    _tmSquarify(items, x, y, w, h, out) {
      if (!items.length) return
      if (items.length === 1) {
        out.push({...items[0], _x: x, _y: y, _w: w, _h: h})
        return
      }
      const side = Math.min(w, h)
      const isWide = w >= h
      let row = []
      let rest = [...items]

      while (rest.length) {
        const next = rest[0]
        const newRow = [...row, next]
        if (!row.length || this._tmWorst(newRow, side) <= this._tmWorst(row, side)) {
          row.push(next)
          rest.shift()
        } else {
          break
        }
      }

      // Якщо жодного елемента не додалось — беремо перший примусово
      if (!row.length) {
        row.push(rest.shift())
      }

      const rowArea = row.reduce((s, i) => s + i._area, 0)

      if (isWide) {
        // Ряд іде зверху вниз, займає смугу зліва
        const colW = rowArea / h
        let py = y
        for (const item of row) {
          const ch = item._area / colW
          out.push({...item, _x: x, _y: py, _w: colW, _h: ch})
          py += ch
        }
        if (rest.length) this._tmSquarify(rest, x + colW, y, w - colW, h, out)
      } else {
        // Ряд іде зліва направо, займає смугу зверху
        const rowH = rowArea / w
        let px = x
        for (const item of row) {
          const cw = item._area / rowH
          out.push({...item, _x: px, _y: y, _w: cw, _h: rowH})
          px += cw
        }
        if (rest.length) this._tmSquarify(rest, x, y + rowH, w, h - rowH, out)
      }
    },

    // ── Загрузка данных ───────────────────────────────────
    async loadData() {
      this.loading = true
      this.error = null
      // Сохраняем предыдущий статус загрузки и блокируем навигацию
      const prevStatus = localStorage.getItem('checkLoadStatus')
      try {
        const res = await fetch(BUDGET_URL)
        const json = await res.json()
        this.rawData = json.budget_info || []
        if (!this.selectedPeriod) {
          const last = this.rawData[this.rawData.length - 1]
          this.selectedPeriod = last?.time || ''
        }
        this.loading = false          // сначала показываем контент
        // Разрешаем навигацию как только данные получены
        localStorage.setItem('checkLoadStatus', 'loaded')
        await this.$nextTick()        // ждём рендер canvas-элементов
        await this.$nextTick()
        this.initCharts()
      } catch (e) {
        this.error = e.message
        this.loading = false
        localStorage.setItem('checkLoadStatus', prevStatus || 'loaded')
      }
    },

    buildCalloutLayout(items, capN = null, r = CALLOUT_R) {
      // Якщо одна категорія забирає левову частку — інші тиснуться у
      // вузький сектор і роздувають розмітку. Об'єднуємо найдрібніші
      // у «Інше», щоб коло не сплющувалось при масштабуванні.
      if (capN && items.length > capN) {
        items = [...items].sort((a, b) => b.value - a.value)
        const head = items.slice(0, capN - 1)
        const tail = items.slice(capN - 1)
        const otherSum = tail.reduce((s, i) => s + i.value, 0)
        head.push({label: this.$t('budget.other'), value: otherSum, color: '#94a3b8'})
        items = head
      }

      const total = items.reduce((s, i) => s + i.value, 0)
      if (!items.length) return {items: [], halfWidth: r, halfHeight: r, total}

      const label = calloutLabel(r)

      const segs = calloutBuildPie(items, r)
      const classified = calloutClassify(segs, r)
      const byZone = z => classified.filter(i => i.zone === z)
      calloutResolveVertical(byZone('left'))
      calloutResolveVertical(byZone('right'))
      calloutResolveHorizontal(byZone('top'))
      calloutResolveHorizontal(byZone('bottom'))

      const leftG = byZone('left'), rightG = byZone('right')
      const topG = byZone('top'), bottomG = byZone('bottom')
      const leftExtent = leftG.length ? Math.max(...leftG.map(i => i.textWidth)) : 0
      const rightExtent = rightG.length ? Math.max(...rightG.map(i => i.textWidth)) : 0
      const leftVSpan = leftG.length ? Math.max(...leftG.map(i => Math.abs(i.rawY) + calloutRowH(i) / 2)) : 0
      const rightVSpan = rightG.length ? Math.max(...rightG.map(i => Math.abs(i.rawY) + calloutRowH(i) / 2)) : 0
      const topSpan = topG.length ? Math.max(...topG.map(i => Math.abs(i.rawX) + i.textWidth / 2)) : 0
      const bottomSpan = bottomG.length ? Math.max(...bottomG.map(i => Math.abs(i.rawX) + i.textWidth / 2)) : 0
      const topRowH = topG.length ? Math.max(...topG.map(calloutRowH)) : 0
      const bottomRowH = bottomG.length ? Math.max(...bottomG.map(calloutRowH)) : 0

      // Стек лево/право може «дотягнутись» вище чи нижче за фіксовану лінію,
      // де зазвичай сидить підпис верх/низ — рахуємо, наскільки далеко він
      // сягає, і за потреби відсуваємо верх/низ ще далі, щоб не перетиналось.
      const sideItems = [...leftG, ...rightG]
      const sideTopReach = sideItems.length ? Math.max(0, ...sideItems.map(i => -(i.rawY - calloutRowH(i) / 2))) : 0
      const sideBottomReach = sideItems.length ? Math.max(0, ...sideItems.map(i => i.rawY + calloutRowH(i) / 2)) : 0
      const topPush = topG.length ? Math.max(0, sideTopReach + CALLOUT_CROSS_BUFFER - label) : 0
      const bottomPush = bottomG.length ? Math.max(0, sideBottomReach + CALLOUT_CROSS_BUFFER - label) : 0

      const halfWidth = Math.max(r, label + leftExtent, label + rightExtent, topSpan + 16, bottomSpan + 16)
      const halfHeight = Math.max(r, leftVSpan + 10, rightVSpan + 10, label + topPush + topRowH, label + bottomPush + bottomRowH)

      const finalItems = classified.map(it => calloutFinalize(it, r, it.zone === 'top' ? topPush : it.zone === 'bottom' ? bottomPush : 0))
      return {items: finalItems, halfWidth, halfHeight, total}
    },

    buildStoreLayout(store, capN = null, includeOpProfit = false, r = CALLOUT_R) {
      const items = EXPENSE_FIELDS
          .map(f => ({
            label: this.$t('budget.fields.' + f),
            value: this.n(store[f]),
            color: STORE_CAT_COLORS[f] || '#475569',
          }))
          .filter(i => i.value > 0)

      // Пиріг тоді показує не просто структуру витрат, а 100% валового
      // прибутку: куди пішли гроші (категорії витрат) + що залишилось
      // (прибуток від діяльності). При збитку сегмент не додаємо —
      // від'ємну частку показати сектором геометрично неможливо,
      // це й так видно текстом у шапці картки.
      if (includeOpProfit) {
        const opProfit = this.rowOpProfit(store)
        if (opProfit > 0) {
          items.push({label: this.$t('budget.opProfit'), value: opProfit, color: '#0c831e'})
        }
      }

      return this.buildCalloutLayout(items, capN, r)
    },

    infocardGradient(store) {
      const m = this.rowMargin(store)
      if (m >= 0.25) return {background: 'linear-gradient(135deg,#22c55e,#059669)'}
      if (m >= 0.15) return {background: 'linear-gradient(135deg,#f59e0b,#d97706)'}
      return {background: 'linear-gradient(135deg,#ef4444,#b91c1c)'}
    },

    makeVBar(ref, labels, datasets, opts = {}) {
      const canvas = this.$refs[ref]
      if (!canvas) return null
      if (this.charts[ref]) this.charts[ref].destroy()

      const isH = opts.indexAxis === 'y'

      const fmtV = v => opts.fullNum
          ? Math.round(v).toLocaleString('uk-UA')
          : opts.pct
              ? (v * 100).toFixed(1) + '%'
              : Math.abs(v) >= 1e6 ? (v / 1e6).toFixed(2) + 'м'
                  : Math.abs(v) >= 1e3 ? (v / 1e3).toFixed(1) + 'т'
                      : Math.round(v).toString()

      // Плагін підписів — горизонтальний або вертикальний режим
      const datalabels = {
        id: 'vbar_datalabels_' + ref,
        afterDatasetsDraw(chart) {
          const {ctx} = chart
          chart.data.datasets.forEach((ds, dsIdx) => {
            if (!chart.isDatasetVisible(dsIdx)) return
            chart.getDatasetMeta(dsIdx).data.forEach((bar, idx) => {
              const v = ds.data[idx]
              if (v == null) return
              const label = fmtV(v)
              ctx.save()
              ctx.fillStyle = '#334155'
              ctx.font = `bold ${datasets.length > 1 ? 10 : 11}px Arial, sans-serif`
              ctx.letterSpacing = '1px'
              if (isH) {
                // Підпис праворуч від бару
                ctx.textAlign = v >= 0 ? 'left' : 'right'
                ctx.textBaseline = 'middle'
                ctx.fillText(label, v >= 0 ? bar.x + 4 : bar.x - 4, bar.y)
              } else {
                const angle = opts.angle ?? -Math.PI / 2
                ctx.translate(bar.x, v >= 0 ? bar.y - 4 : bar.y + 4)
                ctx.rotate(angle)
                ctx.textAlign = v >= 0 ? 'left' : 'right'
                ctx.textBaseline = 'middle'
                ctx.fillText(label, 0, 0)
              }
              ctx.restore()
            })
          })
        },
      }

      const chart = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {labels, datasets},
        options: {
          indexAxis: opts.indexAxis || 'x',
          responsive: true,
          maintainAspectRatio: false,
          layout: {
            padding: isH
                ? {top: 8, right: 52, left: 4, bottom: 8}
                : {top: 52, right: 12, left: 4, bottom: 4},
          },
          plugins: {
            legend: {
              display: datasets.length > 1,
              position: 'top',
              labels: {
                font: {size: 11},
                padding: 16,
                // legendColors задаёт фиксированные цвета для легенды
                // (нужно когда backgroundColor — массив per-bar цветов)
                generateLabels: opts.legendColors
                    ? (chart) => chart.data.datasets.map((ds, i) => ({
                      text: ds.label,
                      fillStyle: opts.legendColors[i] || '#94a3b8',
                      strokeStyle: opts.legendColors[i] || '#94a3b8',
                      lineWidth: 2,
                      hidden: !chart.isDatasetVisible(i),
                      datasetIndex: i,
                    }))
                    : undefined,
              },
            },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: {label: ctx => '  ' + fmtV(ctx.raw)},
            },
          },
          scales: isH ? {
            // Горизонтальний режим: x — значення, y — магазини
            x: {
              grid: {color: 'rgba(0,0,0,0.05)'},
              ticks: {font: {size: 10}, color: '#64748b', callback: v => fmtV(v)},
            },
            y: {
              grid: {display: false},
              ticks: {font: {size: 10}, color: '#475569'},
            },
          } : {
            // Вертикальний режим (стандартний)
            x: {
              grid: {display: false},
              ticks: {maxRotation: 90, minRotation: 90, font: {size: 9}, color: '#64748b'},
            },
            y: {
              grid: {color: 'rgba(0,0,0,0.05)'},
              ticks: {font: {size: 10}, color: '#64748b', callback: v => fmtV(v)},
            },
          },
          animation: {duration: 700, easing: 'easeOutQuart'},
        },
        plugins: [datalabels],
      }))
      this.charts[ref] = chart
      return chart
    },

    initCharts() {
      // 8. Маржинальність — вертикальні стовпці > 1000px, горизонтальні ≤ 1000px
      const axis = this.isNarrowChart ? 'y' : 'x'
      const margRows = this.storesSortedByMargin
      this.makeVBar('chartMargin', margRows.map(r => r.store), [{
        data: margRows.map(r => r._margin),
        backgroundColor: margRows.map(r =>
            r._margin >= 0.25 ? 'rgba(34,197,94,0.85)' :
                r._margin >= 0.15 ? 'rgba(245,158,11,0.85)' : 'rgba(239,68,68,0.85)'),
        borderRadius: 4, borderSkipped: false, label: this.$t('budget.margin'),
      }], {pct: true, indexAxis: axis})
      // 9. Рентабельність — та сама логіка
      const rentRows = this.storesSortedByRentab
      this.makeVBar('chartRentab', rentRows.map(r => r.store), [
        {
          data: rentRows.map(r => r._rentab),
